{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "handleRef",
      "type": "React.Ref<ChatComposerInputHandle>",
      "description": "Imperative handle for programmatic control: insertToken, expandToken, insertText, focus, and getValue."
    },
    {
      "name": "value",
      "type": "string",
      "description": "Controlled input value. Pair with onChange for two-way binding."
    },
    {
      "name": "onChange",
      "type": "(value: string) => void",
      "description": "Called when the input value changes. The serialized string includes token placeholders."
    },
    {
      "name": "placeholder",
      "type": "string",
      "description": "Placeholder text shown when the input is empty.",
      "default": "'Type a message...'"
    },
    {
      "name": "maxRows",
      "type": "number",
      "description": "Maximum visible rows before the input scrolls. Use a lower value in compact layouts.",
      "default": "8"
    },
    {
      "name": "triggers",
      "type": "ChatComposerTrigger[]",
      "description": "Trigger definitions for typeahead menus. Each trigger specifies a character (@ or /), a search source, and an onSelect handler that returns the token to insert. Set hasMultiWordQuery: true when suggestions contain spaces (people, topics): the query then runs to a line break or about 64 characters instead of ending at the first space. Per-trigger emptySearchText (ReactNode) is the message when the query matched nothing."
    },
    {
      "name": "debounceMs",
      "type": "number",
      "description": "Debounce delay for async search sources to avoid excessive network requests.",
      "default": "150"
    },
    {
      "name": "hasHistory",
      "type": "boolean",
      "description": "Enable ArrowUp/Down to recall previously submitted messages.",
      "default": "true"
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible label announced by screen readers.",
      "default": "'Message input'"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the input. Use during streaming or when a prerequisite is unmet.",
      "default": "false"
    },
    {
      "name": "onPaste",
      "type": "(event, text) => boolean | void",
      "description": "Called when plain text is pasted. Return true after handling the text yourself; otherwise ChatComposerInput inserts it or applies paste-as-token behavior."
    },
    {
      "name": "pasteAsToken",
      "type": "UseChatPasteAsTokenReturn | false",
      "description": "Paste-as-token behavior. By default, plain-text pastes over 200 characters become expandable tokens. Pass false to keep every text paste inline, or provide useChatPasteAsToken() to customize the conversion."
    },
    {
      "name": "onFiles",
      "type": "(files: File[]) => void",
      "description": "Called when files are pasted or dropped onto the input. Use to handle attachments."
    },
    {
      "name": "onSubmit",
      "type": "(value: string) => void",
      "description": "Called when the user presses Enter without Shift. The serialized value includes token placeholders."
    },
    {
      "name": "onKeyDown",
      "type": "(event) => void",
      "description": "Key-down handler invoked before the built-in Enter/history behavior (after any open trigger menu). The seam for platform-specific keys: call event.preventDefault() to suppress the default submit (e.g. newline on a touch keyboard), or act on the event yourself to add behavior (e.g. submit on Cmd/Ctrl+Enter). IME composition is always respected; Enter never submits mid-composition."
    },
    {
      "name": "enterKeyHint",
      "type": "'enter' | 'done' | 'go' | 'next' | 'previous' | 'search' | 'send'",
      "description": "What the Return key of a touch keyboard says (the native enterkeyhint). Enter sends the message, so it defaults to send and iOS shows its Send key. When onKeyDown makes Enter insert a line break on touch keyboards, pass enter so the key shows Return again.",
      "default": "'send'"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
